import{_ as d,o as a,c as l,a as s}from"./chunks/framework.Ld7uezS_.js";const b=JSON.parse('{"title":"检测维修保养综合学习课","description":"","frontmatter":{},"headers":[],"relativePath":"course-companion.md","filePath":"course-companion.md","lastUpdated":1787284307000}'),n={name:"course-companion.md"};function r(e,t,i,o,h,p){return a(),l("div",null,[...t[0]||(t[0]=[s(`<h1 id="检测维修保养综合学习课" tabindex="-1">检测维修保养综合学习课 <a class="header-anchor" href="#检测维修保养综合学习课" aria-label="Permalink to &quot;检测维修保养综合学习课&quot;">​</a></h1><blockquote><p>本页把“基础原理、设备差异、检测仪器、故障诊断、理论与技能对应关系”串成一条学习线。它是课程辅助页，不替代现行标准、检测方案、设备说明书、单位规程和鉴定站评分表。</p></blockquote><h2 id="一、先建立总认识-消防设施在解决什么问题" tabindex="-1">一、先建立总认识：消防设施在解决什么问题 <a class="header-anchor" href="#一、先建立总认识-消防设施在解决什么问题" aria-label="Permalink to &quot;一、先建立总认识：消防设施在解决什么问题&quot;">​</a></h2><p>建筑消防设施可以按功能分成五组：</p><table tabindex="0"><thead><tr><th>功能组</th><th>主要解决的问题</th><th>典型设备</th></tr></thead><tbody><tr><td>发现与报警</td><td>尽早发现火灾征兆并发出信息</td><td>感烟/感温探测器、手动报警按钮、火灾报警控制器、声光警报器</td></tr><tr><td>控制与联动</td><td>把报警信号转成控制指令，并接收结果</td><td>消防联动控制器、输入/输出模块、联动逻辑、反馈信号</td></tr><tr><td>灭火与供水</td><td>提供水或其他灭火介质，控制火势</td><td>消防水池/水箱、消防泵、报警阀组、喷头、消火栓、灭火器</td></tr><tr><td>防烟与分隔</td><td>限制烟气和火势扩散，为疏散和救援争取时间</td><td>送风机、排烟风机、风阀、防火门、防火卷帘、防火阀</td></tr><tr><td>疏散与通信</td><td>帮助人员辨认方向、接收指令并保持联系</td><td>应急照明、疏散指示、应急广播、消防电话、消防电梯</td></tr></tbody></table><p>学习任何设备时，都要把它放回这五组功能中。这样才能理解“为什么要检测它”，而不是只记设备名称。</p><h2 id="二、四条主线分别在做什么" tabindex="-1">二、四条主线分别在做什么 <a class="header-anchor" href="#二、四条主线分别在做什么" aria-label="Permalink to &quot;二、四条主线分别在做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工作</th><th>核心问题</th><th>典型产出</th><th>与其他工作的关系</th></tr></thead><tbody><tr><td>设施操作</td><td>按任务让设备或系统产生规定动作</td><td>动作结果、反馈、恢复记录</td><td>操作是认识系统行为的入口</td></tr><tr><td>设施保养</td><td>通过检查、清洁、紧固、状态确认等保持可用</td><td>保养记录、异常报告</td><td>保养发现的问题可能转入维修或检测</td></tr><tr><td>设施维修</td><td>针对异常恢复部件或系统功能</td><td>故障原因、处理记录、复测结果</td><td>维修不能靠复位掩盖，必须验证</td></tr><tr><td>设施检测</td><td>按依据验证系统是否达到规定功能</td><td>检测数据、判定、报告</td><td>检测要综合使用操作、原理、仪器和记录能力</td></tr></tbody></table><p><strong>容易混淆的地方：</strong></p><ul><li>外观干净，不等于功能合格；</li><li>设备动作，不等于反馈正确；</li><li>故障消失，不等于原因已经排除；</li><li>一次末端试水有水，不等于整个系统供水能力合格；</li><li>写了“已处理”，不等于记录具备可追溯性。</li></ul><h2 id="三、零基础统一学习卡-任何知识点都这样读" tabindex="-1">三、零基础统一学习卡：任何知识点都这样读 <a class="header-anchor" href="#三、零基础统一学习卡-任何知识点都这样读" aria-label="Permalink to &quot;三、零基础统一学习卡：任何知识点都这样读&quot;">​</a></h2><p>面对一个新名词或新设备，不要只记一句定义，按下面八个问题展开：</p><ol><li><strong>它是什么</strong>：属于建筑构件、现场设备、控制设备、仪器还是记录对象？</li><li><strong>它解决什么问题</strong>：限制火、限制烟、灭火、疏散、通信、供电还是追溯？</li><li><strong>它由什么组成</strong>：列出本体、连接件、执行机构、供电/水源、控制和反馈部分；</li><li><strong>它怎样工作</strong>：说明输入从哪里来，经过什么判断，输出改变什么状态；</li><li><strong>在哪里使用</strong>：结合场所、系统形式、设计条件和设备适用范围；</li><li><strong>怎样证明正常</strong>：分别写检查、测量、试验、显示、现场动作和反馈证据；</li><li><strong>异常怎样处理</strong>：先记录现象和影响，再按信息、供电、线路/通信、设备、逻辑分层；</li><li><strong>怎样收口</strong>：复测、恢复自动/联动/监视、确认阀门和供电状态，并完成记录。</li></ol><h3 id="例子-为什么-灯亮了-还不能直接写合格" tabindex="-1">例子：为什么“灯亮了”还不能直接写合格 <a class="header-anchor" href="#例子-为什么-灯亮了-还不能直接写合格" aria-label="Permalink to &quot;例子：为什么“灯亮了”还不能直接写合格&quot;">​</a></h3><p>应急照明灯亮，只能说明该灯具在当前观察条件下有发光现象；还要继续核对测试条件、主备电转换、集中电源/控制器故障、疏散方向、照明范围、通信状态和恢复结果。这个例子体现了“单一现象不能替代完整证据链”的通用原则。</p><h2 id="三、设施操作前置课-先学会-我要操作什么" tabindex="-1">三、设施操作前置课：先学会“我要操作什么” <a class="header-anchor" href="#三、设施操作前置课-先学会-我要操作什么" aria-label="Permalink to &quot;三、设施操作前置课：先学会“我要操作什么”&quot;">​</a></h2><p>在进入任何操作卡前，先认识四类角色：输入设备（探测器、手报、水流指示器等）负责把现场状态送进系统；控制显示设备负责接收、分类、显示并发出指令；执行设备负责启动、关闭或播报；反馈信号负责把实际运行、到位或故障状态送回控制器。所谓“控制器有输出”，只代表指令发出，不能代替现场动作和反馈确认。</p><p>学习一项设备操作时，还要先说清五件事：我操作什么、在哪里操作、为什么操作、预期看到什么、结束后恢复什么。若涉及泵、风机、卷帘、电梯、气体灭火或带电部件，必须先确认授权、警戒、监护和专业协同，不能把页面步骤当作自行实操许可。</p><blockquote><p>这一节是后续操作、保养、维修、检测的共同前置。遇到“确认、核对、观察、判断”这些词，先回到这里学习它们具体要确认什么。</p></blockquote><p>在学习消防泵、风机、广播或卷帘的具体动作之前，必须先学会读懂一条操作任务。操作不是“看到按钮就按”，而是把任务单、图纸、控制器信息和现场设备对应起来。</p><h3 id="_6-设备定位的两套地图-建筑地图与系统地图" tabindex="-1">6. 设备定位的两套地图：建筑地图与系统地图 <a class="header-anchor" href="#_6-设备定位的两套地图-建筑地图与系统地图" aria-label="Permalink to &quot;6. 设备定位的两套地图：建筑地图与系统地图&quot;">​</a></h3><p>零基础容易把“房间位置”和“控制器编号”当成一回事。实际上要同时看两套地图：</p><ul><li><strong>建筑地图</strong>回答“设备 physically 在哪里”：楼层、房间、防火分区、防烟分区、泵房或风机房；</li><li><strong>系统地图</strong>回答“设备如何被系统找到”：控制器、回路、地址、模块、点位名称和联动关系。</li></ul><p>两套地图必须互相对上。控制器显示某地址时，先通过点位表或竣工图找到建筑位置，再到现场核对铭牌、设备外观和周边对象；建筑位置相同或相近的设备，也不能因为“看起来像”就认为是同一个点位。若两套地图对不上，应停止扩大操作范围，保留差异并报告核查。</p><h3 id="_7-报警系统与水系统都要看三类证据" tabindex="-1">7. 报警系统与水系统都要看三类证据 <a class="header-anchor" href="#_7-报警系统与水系统都要看三类证据" aria-label="Permalink to &quot;7. 报警系统与水系统都要看三类证据&quot;">​</a></h3><p>学习报警系统时，三类证据是控制器显示、现场设备动作和反馈信号；学习水系统时，还要增加水位、压力、流量、出水和排水等水力证据。它们分别回答“系统看到了什么”“设备做了什么”“结果有没有返回”“供水过程是否成立”。任何一类缺失，都只能形成局部观察，不能直接写成完整合格结论。</p><p>把检测过程写成一句完整的话，可以使用下面的顺序：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>什么条件触发</span></span>
<span class="line"><span>→ 控制器识别并显示什么</span></span>
<span class="line"><span>→ 哪个现场设备发生什么动作</span></span>
<span class="line"><span>→ 哪个反馈或水力现象证明结果</span></span>
<span class="line"><span>→ 测试/维修后恢复了什么</span></span></code></pre></div><p>例如“末端试水有水”只回答了最后端出现了水流现象，还没有回答控制阀是否处于规定位置、报警阀和水流指示器是否动作、控制器是否收到分区信号、泵组是否按设计逻辑响应以及测试后是否恢复。因此，看到课程中的“观察反馈”“确认恢复”时，要沿这条证据链逐项核对，不要把它当成一句可以直接背诵的结论。</p><h3 id="_1-把任务拆成五个问题" tabindex="-1">1. 把任务拆成五个问题 <a class="header-anchor" href="#_1-把任务拆成五个问题" aria-label="Permalink to &quot;1. 把任务拆成五个问题&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>要确认的内容</th><th>初学者要找的证据</th></tr></thead><tbody><tr><td>谁</td><td>谁提出任务、谁授权、谁负责现场监护</td><td>任务单、交接记录、现场负责人</td></tr><tr><td>哪里</td><td>建筑、楼层、房间、防火分区、报警区域、设备地址</td><td>图纸、地址标签、控制器显示、设备铭牌</td></tr><tr><td>什么</td><td>输入设备、控制器、执行设备还是反馈点</td><td>设备外观、名称、编号、系统图</td></tr><tr><td>为什么</td><td>查询、控制、测试、恢复还是交接报告</td><td>任务目的和方案要求</td></tr><tr><td>完成什么</td><td>要看到显示、动作、反馈、测量结果还是恢复状态</td><td>预期结果、记录字段和结束条件</td></tr></tbody></table><h3 id="_2-先学会区分四层对象" tabindex="-1">2. 先学会区分四层对象 <a class="header-anchor" href="#_2-先学会区分四层对象" aria-label="Permalink to &quot;2. 先学会区分四层对象&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入对象：探测器、手报、水流指示器、压力开关</span></span>
<span class="line"><span>    ↓ 提供火警、状态或压力/水流信息</span></span>
<span class="line"><span>控制对象：报警控制器、联动控制器、控制柜、模块</span></span>
<span class="line"><span>    ↓ 接收、判断或发出指令</span></span>
<span class="line"><span>执行对象：泵、风机、风阀、广播、卷帘、照明</span></span>
<span class="line"><span>    ↓ 改变现场设备状态</span></span>
<span class="line"><span>反馈对象：运行、到位、故障触点、输入模块、控制器显示</span></span>
<span class="line"><span>    ↓ 证明动作结果或提示异常</span></span></code></pre></div><p>例如“测试风机”不是一个完整对象描述，至少要继续确认：哪一台风机、服务哪个区域、从哪里发出指令、风阀是否参与、现场是否运行、控制器是否收到反馈、结束后恢复什么状态。</p><h3 id="_3-区域为什么必须核对" tabindex="-1">3. 区域为什么必须核对 <a class="header-anchor" href="#_3-区域为什么必须核对" aria-label="Permalink to &quot;3. 区域为什么必须核对&quot;">​</a></h3><p>“某层”“附近”“东侧”都可能不够精确。区域要与图纸、防火分区/防烟分区、报警区域、控制器地址、设备铭牌和现场位置互相核对。同一建筑可能有相邻分区、同名房间和多台同类设备，选错区域会造成误报警、误联动或遗漏真正故障。</p><h3 id="_4-零基础任务复述模板" tabindex="-1">4. 零基础任务复述模板 <a class="header-anchor" href="#_4-零基础任务复述模板" aria-label="Permalink to &quot;4. 零基础任务复述模板&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要对【位置/分区/地址】的【设备或功能】执行【查询/控制/测试/恢复】；</span></span>
<span class="line"><span>目的是【验证或处理什么】；</span></span>
<span class="line"><span>预期看到【控制器显示/现场动作/反馈】；</span></span>
<span class="line"><span>结束后恢复【自动/联动/监视、阀门、供电等状态】。</span></span></code></pre></div><p>五项中有一项说不清，就先查任务单、图纸、说明书或询问授权人员，不直接操作真实设备。这个模板也适合只读训练：先看场景，再尝试口头填空，最后对照答案。</p><h3 id="_5-一个完整例子" tabindex="-1">5. 一个完整例子 <a class="header-anchor" href="#_5-一个完整例子" aria-label="Permalink to &quot;5. 一个完整例子&quot;">​</a></h3><p>任务：“确认某防烟分区排烟风机联动是否正常。”</p><ul><li><strong>对象</strong>：不是泛指“排烟系统”，而是指定风机、相关风阀、控制器输出和反馈点；</li><li><strong>区域</strong>：核对防烟分区、风机编号、控制器地址和现场位置；</li><li><strong>目的</strong>：验证联动信号链，不是随意启动设备；</li><li><strong>前置</strong>：确认授权、人员清场、疏散影响、联动范围和恢复责任；</li><li><strong>结果</strong>：分别记录输入条件、控制器输出、风机运行、风阀位置和反馈；</li><li><strong>收口</strong>：按方案停止或复位，恢复自动/联动/监视并记录异常。</li></ul><p>这就是“确认任务和对象”背后的完整知识，不是简单记忆一句操作口诀。</p><h2 id="三、三类设备系统对比学习" tabindex="-1">三、三类设备系统对比学习 <a class="header-anchor" href="#三、三类设备系统对比学习" aria-label="Permalink to &quot;三、三类设备系统对比学习&quot;">​</a></h2><h3 id="_1-火灾自动报警系统" tabindex="-1">1. 火灾自动报警系统 <a class="header-anchor" href="#_1-火灾自动报警系统" aria-label="Permalink to &quot;1. 火灾自动报警系统&quot;">​</a></h3><p>**基本原理：**探测器或人工报警设备产生输入，报警控制器识别地址和类别，联动控制器按设计逻辑发出控制，现场设备动作后再通过输入模块或反馈触点把状态返回控制器。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>探测器/手报</span></span>
<span class="line"><span>→ 报警控制器显示火警</span></span>
<span class="line"><span>→ 联动控制器按逻辑输出</span></span>
<span class="line"><span>→ 泵/风机/广播/卷帘等动作</span></span>
<span class="line"><span>→ 运行、到位或故障反馈</span></span>
<span class="line"><span>→ 复位并恢复规定监视状态</span></span></code></pre></div><p><strong>重点差异：</strong></p><ul><li>探测器负责感知，不等于控制器；</li><li>输入模块负责采集现场状态，输出模块负责发出控制；</li><li>控制器显示“输出”不等于执行机构已经动作；</li><li>火警、故障、监管、屏蔽/隔离是不同信息类别，不能混为一谈。</li></ul><h3 id="_2-消防给水和自动灭火系统" tabindex="-1">2. 消防给水和自动灭火系统 <a class="header-anchor" href="#_2-消防给水和自动灭火系统" aria-label="Permalink to &quot;2. 消防给水和自动灭火系统&quot;">​</a></h3><p>**基本原理：**水源和储水设施提供水量，泵组提供压力和流量，管网把水输送到保护区域，报警阀组、水流指示器、压力开关等完成分区控制和信号反馈，喷头或消火栓完成灭火介质释放。</p><p><strong>学习重点：</strong></p><ul><li>泵启动后要观察运行、压力、控制柜和反馈，不能只看电机转动；</li><li>控制阀状态会直接影响保护范围，不能未经授权改变；</li><li>末端试水用于验证相应测试点及信号链，不能据此推算全系统性能；</li><li>湿式、干式、预作用、雨淋系统的充水和控制逻辑不同，先确认系统形式再学习操作。</li></ul><h3 id="_3-其他消防设施" tabindex="-1">3. 其他消防设施 <a class="header-anchor" href="#_3-其他消防设施" aria-label="Permalink to &quot;3. 其他消防设施&quot;">​</a></h3><table tabindex="0"><thead><tr><th>系统</th><th>主要功能</th><th>与报警/联动的关系</th><th>关键差异</th></tr></thead><tbody><tr><td>防烟排烟</td><td>控制烟气流向和排出烟气</td><td>可能接收联动输出并返回运行/故障反馈</td><td>风机动作还要核对风阀和反馈</td></tr><tr><td>防火门/卷帘/防火阀</td><td>防止火焰和烟气蔓延</td><td>可由联动控制或现场机构动作</td><td>机械运动区域必须先清场</td></tr><tr><td>应急照明/疏散指示</td><td>提供疏散照明和方向信息</td><td>受集中电源、控制器或自带电源监视</td><td>灯具点亮不等于集中电源无故障</td></tr><tr><td>应急广播/消防电话</td><td>传递疏散指令和保持通信</td><td>可能按分区联动或由控制室操作</td><td>必须核对目标分区和实际可听/可通话效果</td></tr><tr><td>消防电梯</td><td>为消防救援提供专用运行条件</td><td>迫降信号、状态和反馈受预案约束</td><td>不能当作普通演示设备随意测试</td></tr></tbody></table><h2 id="四、建筑防火概念深学-从-名词-到-能判断" tabindex="-1">四、建筑防火概念深学：从“名词”到“能判断” <a class="header-anchor" href="#四、建筑防火概念深学-从-名词-到-能判断" aria-label="Permalink to &quot;四、建筑防火概念深学：从“名词”到“能判断”&quot;">​</a></h2><p>建筑防火不是只背几种设施名称，而是回答三个问题：<strong>火会向哪里扩散？烟会向哪里扩散？建筑和构件能坚持多久？</strong></p><h3 id="_1-五个概念先按对象分类" tabindex="-1">1. 五个概念先按对象分类 <a class="header-anchor" href="#_1-五个概念先按对象分类" aria-label="Permalink to &quot;1. 五个概念先按对象分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>它描述的对象</th><th>主要解决的问题</th><th>典型例子</th></tr></thead><tbody><tr><td>防火分区</td><td>建筑内部的区域边界</td><td>限制火焰、热量和燃烧产物扩大</td><td>防火墙、防火门、防火卷帘、防火封堵</td></tr><tr><td>防烟分区</td><td>建筑内部的烟气控制区域</td><td>限制烟气水平扩散、组织排烟</td><td>挡烟垂壁、排烟口、排烟风机、加压送风</td></tr><tr><td>防火间距</td><td>相邻建筑之间的空间</td><td>降低建筑之间相互延烧风险</td><td>两栋建筑之间的安全距离</td></tr><tr><td>耐火极限</td><td>单个构件或构件组合的性能时间</td><td>判断构件在规定火作用下能坚持多久</td><td>防火墙、楼板、梁、柱、防火门</td></tr><tr><td>耐火等级</td><td>整栋建筑的耐火能力分级</td><td>判断建筑整体防火结构体系处于哪一档</td><td>一级、二级、三级、四级耐火等级</td></tr></tbody></table><h3 id="_2-耐火极限与耐火等级的关系" tabindex="-1">2. 耐火极限与耐火等级的关系 <a class="header-anchor" href="#_2-耐火极限与耐火等级的关系" aria-label="Permalink to &quot;2. 耐火极限与耐火等级的关系&quot;">​</a></h3><p>可以按下面的因果关系理解：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>墙、柱、梁、楼板、屋顶承重构件等单个构件</span></span>
<span class="line"><span>→ 分别具有承载、完整、隔热等耐火性能</span></span>
<span class="line"><span>→ 这些构件按建筑用途和部位组合使用</span></span>
<span class="line"><span>→ 对整栋建筑形成耐火等级</span></span></code></pre></div><p>因此：</p><ul><li>防火门有较高耐火性能，不代表整栋建筑就是一级耐火等级；</li><li>建筑属于某个耐火等级，也不代表所有构件的耐火极限都完全相同；</li><li>“耐火极限几小时”是构件性能时间，“耐火等级一级至四级”是建筑整体分级；</li><li>具体构件的耐火极限要求必须按建筑类型、构件部位、材料和现行标准表格核对。</li></ul><h3 id="_3-耐火等级四级框架" tabindex="-1">3. 耐火等级四级框架 <a class="header-anchor" href="#_3-耐火等级四级框架" aria-label="Permalink to &quot;3. 耐火等级四级框架&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等级</th><th>学习上的直观理解</th><th>不能产生的误解</th></tr></thead><tbody><tr><td>一级</td><td>整体耐火能力要求最高，主要构件体系的耐火要求最严格</td><td>不是某一堵墙耐火时间长就自动成为一级</td></tr><tr><td>二级</td><td>整体耐火能力较高，常见建筑中应用较多，但要结合条件判断</td><td>不是所有构件都比一级固定少同样时间</td></tr><tr><td>三级</td><td>整体耐火能力要求低于一、二级，适用建筑和条件受到更多限制</td><td>不能只看建筑外观或材料名称判断</td></tr><tr><td>四级</td><td>常用框架中整体耐火能力要求最低，适用范围限制更严格</td><td>不能脱离建筑用途、高度和现行规范直接判定允许采用</td></tr></tbody></table><h3 id="_4-五个概念的快速判断" tabindex="-1">4. 五个概念的快速判断 <a class="header-anchor" href="#_4-五个概念的快速判断" aria-label="Permalink to &quot;4. 五个概念的快速判断&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>建筑内部限制火势范围 → 防火分区</span></span>
<span class="line"><span>建筑内部限制烟气扩散 → 防烟分区</span></span>
<span class="line"><span>相邻建筑之间的距离 → 防火间距</span></span>
<span class="line"><span>单个构件能保持性能多久 → 耐火极限</span></span>
<span class="line"><span>整栋建筑处于哪一档耐火能力 → 耐火等级</span></span></code></pre></div><p>**对应技能：**看到防火门闭合器损坏、防火卷帘下有障碍、防烟风机有输出但无反馈时，不能只背“这是防火设施”，还要说明它保护的是火势边界、烟气边界还是疏散路径，并据此决定记录、报告、维修、复测和恢复方式。</p><h2 id="五、检测仪器学习卡" tabindex="-1">五、检测仪器学习卡 <a class="header-anchor" href="#五、检测仪器学习卡" aria-label="Permalink to &quot;五、检测仪器学习卡&quot;">​</a></h2><p>仪器学习不追求背品牌，而是掌握“用途—使用前检查—测量过程—记录—判定边界”。</p><table tabindex="0"><thead><tr><th>仪器/工具类别</th><th>主要用途</th><th>使用前检查</th><th>使用时注意</th><th>记录内容</th></tr></thead><tbody><tr><td>万用表等电气测量工具</td><td>按方案测量电压、通断或相关电气状态</td><td>型号、量程、表笔、绝缘外观、电池和校准状态</td><td>先确认被测对象、测量类别和安全等级，严禁把电流档误接入不适合回路</td><td>仪器编号、档位、单位、读数、测点、时间</td></tr><tr><td>绝缘/电气专项测试工具</td><td>按适用依据检查绝缘或相关电气性能</td><td>测试电压范围、接线、放电要求、校准状态</td><td>由授权人员按方案隔离被测设备，测试后确认放电和恢复</td><td>测试对象、方法、读数、单位、依据和恢复结果</td></tr><tr><td>压力表/压力测试工具</td><td>观察或测量水系统压力</td><td>量程、接口、密封、指针/显示、检定状态</td><td>先确认系统形式、测点、阀门和排水条件；压力值必须有适用判定依据</td><td>测点、时间、压力、单位、系统状态、依据</td></tr><tr><td>风速/风量相关仪器</td><td>按方案测量送风、排烟或气流状态</td><td>量程、探头方向、校准和环境条件</td><td>先确定测量位置、截面和方法，不把单点读数直接泛化为系统结论</td><td>测点、方法、环境、读数、单位和判定依据</td></tr><tr><td>声级计</td><td>按方案评价警报、广播或声响效果</td><td>量程、频率/计权设置、校准状态</td><td>按检测方案确定位置和背景条件，避免把环境噪声当设备结果</td><td>测点、背景条件、读数、单位、仪器和依据</td></tr><tr><td>烟雾/温感模拟工具</td><td>在授权测试中模拟探测器输入</td><td>工具适配性、电量、输出状态和设备说明书</td><td>按探测器类型、说明书和方案操作，防止真实联动误启动</td><td>探测器地址、模拟方式、显示、警报、反馈和恢复</td></tr><tr><td>通断/反馈检查工具</td><td>辅助核对触点、模块或反馈链</td><td>接线、量程、极性和仪器状态</td><td>不得用短接方式伪造“正常反馈”，测试须按方案进行</td><td>测点、状态、方法、原始结果和恢复</td></tr></tbody></table><h3 id="检测仪器的选择依据与基本操作" tabindex="-1">检测仪器的选择依据与基本操作 <a class="header-anchor" href="#检测仪器的选择依据与基本操作" aria-label="Permalink to &quot;检测仪器的选择依据与基本操作&quot;">​</a></h3><p>选择工具时先确定要证明的是电气状态、绝缘性能、水力压力、气流性能、声响效果、探测器输入，还是现场反馈；再核对量程/设置、探头或接口匹配、环境条件、校准/检定状态和安全等级。仪器不能替代检测方案，也不能把相邻指标互相替代。</p><ul><li><strong>万用表</strong>：用于方案允许的电压、通断、电阻等电气检查。使用前检查表笔绝缘、插孔、保险、量程、电池和校准状态；先选功能和量程再接线，严禁电流档并联测量或把蜂鸣通断当作系统功能结论。</li><li><strong>绝缘测试工具</strong>：用于明确要求的线路/设备绝缘检查。使用前核对测试电压范围、导线、接线、放电功能和校准状态；必须断电、验电、隔离，测试后放电并确认恢复，不能对未隔离回路直接测试。</li><li><strong>压力测试工具</strong>：用于水系统指定测点。检查量程、接口、密封、零点和校准状态；按方案缓慢取压并记录系统状态、测点、单位和时间，不能将静态压力外推为流量或全系统性能。</li><li><strong>风速/风量仪器</strong>：用于方案指定的送风/排烟测量。检查探头方向、量程、截面方法和环境条件；按布点方法记录各点原始值与计算方法，不能用单点读数代表整截面。</li><li><strong>声级计</strong>：用于报警、广播等声响评价。检查量程、计权/响应设置、传声器、电池和校准；记录测点、背景条件和分区，不能把背景噪声或一次读数直接作为设备结论。</li><li><strong>烟温模拟工具</strong>：用于与探测器类型匹配的授权测试。检查适配性、电量和输出状态，按说明书/方案触发并记录显示、警报、反馈、复位；不得用真实烟火、随意热源或不适配介质替代。</li><li><strong>反馈/通断工具</strong>：用于核对触点、模块或反馈链。检查接线、极性、量程和仪器状态，按图纸和方案测量原状态并在结束后恢复；不得短接、拔线或外加信号伪造正常反馈。</li></ul><p>所有仪器都应记录名称、型号/编号、量程或设置、校准/检定状态、测点、单位、原始读数、时间和环境条件。异常时先保留首次记录，检查接线、测点、量程、仪器状态和系统条件，再按同一依据或指定方法复测；复测不得覆盖原始异常。</p><h3 id="检测仪器的通用步骤" tabindex="-1">检测仪器的通用步骤 <a class="header-anchor" href="#检测仪器的通用步骤" aria-label="Permalink to &quot;检测仪器的通用步骤&quot;">​</a></h3><ol><li>明确检测对象、目的、测点、预期结果和判定依据；</li><li>查阅适用标准、检测方案、图纸、设备说明书和历史记录；</li><li>核对仪器名称、编号、量程、分辨力、校准/检定状态和电池；</li><li>检查探头、表笔、接线、接口和现场安全条件；</li><li>按方案测量或触发，记录原始读数和现场状态，不先写结论；</li><li>将输入、控制器显示、现场动作、反馈和恢复逐项对应；</li><li>发现异常时保留原始记录，判断保护影响并报告；</li><li>维修或调整后按授权复测，单独记录复测结果；</li><li>确认自动、联动、监视、阀门、供电和其他规定状态恢复；</li><li>完成报告，写明依据、仪器、方法、结果、结论和后续措施。</li></ol><blockquote><p>具体精度、允许误差、测量位置、抽检比例、动作时间和合格阈值，必须以适用标准、检测方案、设备说明书和鉴定站要求为准；本站不提供脱离依据的统一数值。</p></blockquote><h2 id="五、按系统组织检测步骤" tabindex="-1">五、按系统组织检测步骤 <a class="header-anchor" href="#五、按系统组织检测步骤" aria-label="Permalink to &quot;五、按系统组织检测步骤&quot;">​</a></h2><h3 id="报警与联动" tabindex="-1">报警与联动 <a class="header-anchor" href="#报警与联动" aria-label="Permalink to &quot;报警与联动&quot;">​</a></h3><ul><li><strong>检测前</strong>：确认地址/区域、触发目的、预期联动和判定依据；查图纸、方案、说明书、历史记录及屏蔽/隔离清单；通知控制室和相关岗位，确认警报、泵、风机、卷帘、广播、电梯或气体灭火是否会动作，落实授权、监护和恢复责任。</li><li><strong>检测中</strong>：用匹配的烟温模拟工具、手报操作或方案指定输入触发；分别记录输入时间、控制器显示、输出、现场动作、运行/到位/故障反馈和必要测量值。不得用短接、拔线、随意加烟加热或反复真实联动替代规范方法。</li><li><strong>检测后</strong>：按方案复位输入和控制器，恢复自动/联动/监视、主备电及屏蔽/隔离状态；核对现场和控制室无新增故障，形成对象、方法、原始结果、判定依据、异常、复测和恢复记录。</li><li><strong>边界</strong>：有输出不等于设备动作，设备动作不等于反馈成立；输入、显示、动作、反馈、恢复任一项缺证据，不能笼统判定合格。</li></ul><h3 id="水系统" tabindex="-1">水系统 <a class="header-anchor" href="#水系统" aria-label="Permalink to &quot;水系统&quot;">​</a></h3><ul><li><strong>检测前</strong>：确认湿式/干式等系统形式、分区、测试点、授权、排水和防淹条件；核对水源/水位、阀门、供电、控制方式、压力测点和控制室监视；准备匹配的压力/流量或反馈工具并确认量程、接口、校准/检定状态。</li><li><strong>检测中</strong>：按方案验证泵组、主备切换、报警阀组、末端试水、水流指示器、压力开关或消火栓；记录触发条件、压力/流量及单位、仪器、现场水力动作、警铃/泵动作、控制室显示和反馈。不得擅自关阀、改设定、扩大放水或人为制造故障。</li><li><strong>检测后</strong>：停止放水/试验，确认排水完成、无渗漏、阀门和控制方式恢复，自动/联动/监视及控制室信息正常；记录测试条件、原始值、依据、异常、临时措施、复测和复核人。</li><li><strong>边界</strong>：末端有水不等于全系统供水合格，电机运转不等于泵组功能合格，压力表有读数不等于仪表准确；压力、流量、时间和允许误差必须回查适用依据。</li></ul><h3 id="其他消防设施" tabindex="-1">其他消防设施 <a class="header-anchor" href="#其他消防设施" aria-label="Permalink to &quot;其他消防设施&quot;">​</a></h3><ul><li><strong>检测前</strong>：按对象确认区域、动作范围和安全条件；防烟排烟核对风机/风阀、测风截面和风速风量方法，卷帘清场，电梯联系维保单位，照明/广播/电话确认主备电与分区，消火栓确认排水；落实机械运动、电气和误动作防护。</li><li><strong>检测中</strong>：按方案验证风机运行、风阀到位、风速/风量、门卷帘/防火阀、应急转换、照明/广播/电话、电梯迫降接口和消火栓组件；分别记录命令、现场动作、反馈、仪器设置和原始值，不把风机转动、单灯点亮、单扬声器有声或门体移动当作完整结论。</li><li><strong>检测后</strong>：恢复风机/阀门、门卷帘、照明主电、广播电话常态、电梯正常服务及消火栓阀门/排水；核对控制室自动/联动/监视与故障信息，清点临时隔离并记录遗留问题。</li><li><strong>边界</strong>：照度、转换时间、持续时间、风量风压、声级和动作时间不得脱离设计文件、现行标准、说明书、检测方案或专业协同结论写死；性能数据、反馈和恢复缺一项时只能待复核或判定不符合相应要求。</li></ul><blockquote><p>三类检测共同遵循：<strong>检测前确认依据、范围、授权、仪器和风险；检测中按方法取证并记录原始值；检测后复原现场、核对监视、保留异常并按同一依据复测。</strong></p></blockquote><h2 id="六、常见故障诊断总表" tabindex="-1">六、常见故障诊断总表 <a class="header-anchor" href="#六、常见故障诊断总表" aria-label="Permalink to &quot;六、常见故障诊断总表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>优先假设</th><th>判断依据</th><th>排查顺序</th><th>不能做什么</th></tr></thead><tbody><tr><td>单个探测器故障</td><td>污染、进水、底座接触、地址或局部线路</td><td>地址、时间、环境、同回路其他设备状态</td><td>记录 → 看范围 → 查可见安装和环境 → 按授权测试/更换 → 复测</td><td>直接拔掉或屏蔽后写“正常”</td></tr><tr><td>多个设备同时通信异常</td><td>供电、回路、通信链路、隔离器或施工影响</td><td>同回路/分区/时间范围是否成片异常</td><td>先看共同原因，再做分段测试</td><td>逐个盲目换设备、短接线路</td></tr><tr><td>主备电故障</td><td>供电开关、保险、接线、蓄电池或充电部分</td><td>主电/备用电状态、切换结果、控制器信息</td><td>按授权断电、验电、隔离 → 检查 → 复测</td><td>反复拔插电池、带电拆装</td></tr><tr><td>控制器有输出、现场不动作</td><td>电源、控制方式、模块、执行机构或线路</td><td>输出时间、现场电源、执行机构和反馈状态</td><td>区分未输出/未动作/无反馈</td><td>只看控制器显示就写联动成功</td></tr><tr><td>水泵启动但无压力</td><td>阀门、水源、泵组、管路、压力测点或仪表</td><td>泵运行、阀门、水源、压力变化和异常声音</td><td>先保安全和记录，再按方案分层核对</td><td>擅自关阀、改压力设定、反复启停</td></tr><tr><td>末端试水有水但无报警</td><td>水流指示器、压力开关、模块、线路或控制器输入</td><td>测试点、阀门、排水、信号链和显示</td><td>保留试水条件 → 分段核对信号链 → 恢复</td><td>把“有水”写成全系统合格</td></tr><tr><td>风机动作但风阀无反馈</td><td>风阀执行机构、限位、反馈触点、模块或线路</td><td>风机运行、风阀实际位置、反馈显示</td><td>清场 → 区分动作和反馈 → 授权检查</td><td>站在运动区域反复启动</td></tr><tr><td>卷帘中途停止</td><td>障碍、机械、供电、限位、控制或反馈</td><td>停止位置、现场障碍、控制器、限位和电源</td><td>立即保护人员 → 记录 → 专业检查 → 方案复测</td><td>站在下方观察或反复启动</td></tr><tr><td>应急照明灯亮但系统故障</td><td>集中电源、通信、充电、控制器或线路</td><td>灯具状态与集中电源/控制器状态是否一致</td><td>记录故障 → 核对电源和通信 → 转维修/检测 → 恢复</td><td>只凭灯亮结束工单</td></tr></tbody></table><h3 id="故障诊断的统一思路" tabindex="-1">故障诊断的统一思路 <a class="header-anchor" href="#故障诊断的统一思路" aria-label="Permalink to &quot;故障诊断的统一思路&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>记录现象</span></span>
<span class="line"><span>→ 判断影响范围</span></span>
<span class="line"><span>→ 按信息/供电/线路通信/现场设备/逻辑配置分层</span></span>
<span class="line"><span>→ 先查共同原因和低风险可见项</span></span>
<span class="line"><span>→ 落实授权、隔离和临时防护</span></span>
<span class="line"><span>→ 处理或升级</span></span>
<span class="line"><span>→ 复测输入、显示、动作、反馈、恢复</span></span>
<span class="line"><span>→ 记录依据和遗留风险</span></span></code></pre></div><h2 id="六、维修闭环扩展-三类故障的共同判断框架" tabindex="-1">六、维修闭环扩展：三类故障的共同判断框架 <a class="header-anchor" href="#六、维修闭环扩展-三类故障的共同判断框架" aria-label="Permalink to &quot;六、维修闭环扩展：三类故障的共同判断框架&quot;">​</a></h2><p><code>skill/04-repair.md</code> 已按报警、水系统、其他消防设施分别建立 12 个故障案例，共 36 个案例。课程学习时，每个案例都沿用同一条证据链：</p><table tabindex="0"><thead><tr><th>环节</th><th>学习要求</th></tr></thead><tbody><tr><td>现象与影响</td><td>记录原始显示、时间、地址/区域、当前状态和保护影响，区分单点、局部、成片异常</td></tr><tr><td>五层原因</td><td>依次考虑信息、供电、线路/通信、现场设备、逻辑/配置，不把猜测写成结论</td></tr><tr><td>判断与排查</td><td>先查共同原因和低风险可见项，再按授权分层测试；保留首次异常，不用复位覆盖</td></tr><tr><td>边界与防护</td><td>明确哪些动作只能由授权/专业人员执行；涉及停用、带电、放水、联动、机械运动时落实临时防护</td></tr><tr><td>复测与记录</td><td>分别核对输入、显示、动作、反馈、恢复，记录依据、方法、部件、原始/复测结果、遗留风险和复核人</td></tr></tbody></table><p><strong>共同原因</strong>优先看同一时间、同一区域/回路、同一供电源、同一通信链路和近期施工/进水/环境变化。<strong>升级条件</strong>包括保护范围扩大缺失、主备电能力不确定、成片离线、泵组/阀门/水源受影响、联动逻辑或保护参数、气体灭火/电梯/高处/带电/机械运动，以及重复故障或超出授权范围。无法恢复自动、联动、监视时，不能关闭工单。</p><p>具体压力、流量、动作时间、声光或照度判定不得脱离适用标准、设计文件、检测方案、设备说明书和鉴定站要求写死；课程只提供诊断结构和记录要求。</p><h2 id="七、理论知识如何对应技能操作" tabindex="-1">七、理论知识如何对应技能操作 <a class="header-anchor" href="#七、理论知识如何对应技能操作" aria-label="Permalink to &quot;七、理论知识如何对应技能操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>理论知识</th><th>技能应用</th><th>学习时要回答的问题</th></tr></thead><tbody><tr><td>燃烧和火灾</td><td>初起火灾处置、探测器和报警判断</td><td>为什么要先报警、疏散和保护人员？</td></tr><tr><td>建筑防火</td><td>防火分区、防火门、卷帘、防烟分隔</td><td>这个设备保护什么区域，动作会影响什么？</td></tr><tr><td>电气消防</td><td>主备电、线路、接地、断电验电和故障诊断</td><td>这个现象属于供电、线路还是设备本体？</td></tr><tr><td>消防设施原理</td><td>报警、联动、泵组、风机和反馈检测</td><td>输入、控制、输出和反馈分别在哪里？</td></tr><tr><td>计算机与记录</td><td>控制器查询、日志、时间、记录和报告</td><td>原始现象是否完整、可追溯、未被覆盖？</td></tr><tr><td>法律法规与标准</td><td>选择检测依据、区分设计/验收/维护责任</td><td>当前问题应该查哪一类文件？</td></tr><tr><td>安全生产与职业健康</td><td>停用、隔离、监护、危险作业和恢复</td><td>哪些动作不能自行做，什么时候必须停止？</td></tr><tr><td>职业道德与消防工作</td><td>如实记录、报告异常、岗位边界</td><td>是否把未解决故障写成已处理？</td></tr></tbody></table><h3 id="一道技能题的理论联动示例" tabindex="-1">一道技能题的理论联动示例 <a class="header-anchor" href="#一道技能题的理论联动示例" aria-label="Permalink to &quot;一道技能题的理论联动示例&quot;">​</a></h3><p>**场景：**控制器显示风机输出，现场风机启动，但没有运行反馈。</p><ul><li>消防设施原理：知道输出和反馈是信号链的不同环节；</li><li>电气消防：知道要考虑供电、控制柜、线路和触点；</li><li>建筑防火：知道防烟排烟关系人员疏散，不能随意停用；</li><li>安全生产：知道运动部件区域要清场，维修要授权隔离；</li><li>计算机与记录：知道记录输出时间、现场动作、反馈缺失和恢复结果；</li><li>设施维修/检测：知道区分“未输出、未动作、动作无反馈”，处理后重新复测。</li></ul><p>这就是理论和技能的对应关系：理论不是独立背诵，技能题是理论在具体设备和现场条件中的应用。</p><h2 id="八、十章理论—设备原理—技能项目—训练题学习表" tabindex="-1">八、十章理论—设备原理—技能项目—训练题学习表 <a class="header-anchor" href="#八、十章理论—设备原理—技能项目—训练题学习表" aria-label="Permalink to &quot;八、十章理论—设备原理—技能项目—训练题学习表&quot;">​</a></h2><p>下面的表是学习导航和复习索引：每章先读理论，再回到对应设备原理，最后用操作、保养、维修、检测项目和训练题检查是否能解释“为什么、看什么、如何恢复”。题号是本站原创只读训练题/场景题编号，不代表官方题库或鉴定站评分表。</p><table tabindex="0"><thead><tr><th>理论章节</th><th>对应设备原理</th><th>操作项目</th><th>保养项目</th><th>维修项目</th><th>检测项目</th><th>训练题编号</th><th>学习产出</th></tr></thead><tbody><tr><td>1. 职业道德</td><td>如实记录、复核、报告使信号链证据可追溯</td><td>报警信息处置与状态恢复</td><td>发现异常不隐瞒</td><td>故障原因未明不得写已排除</td><td>原始值、复测值、结论分开</td><td>T01、T15、T28；S01、S06、S23</td><td>能按岗位边界记录和升级</td></tr><tr><td>2. 消防工作概述</td><td>单位责任与设施持续可用的关系</td><td>报警、联动和岗位协同</td><td>交接、巡查、异常报告</td><td>保护影响扩大时升级</td><td>依据、范围、责任和报告对象</td><td>T02、T16、T29；S01、S06、S25</td><td>能说明谁负责、何时报告</td></tr><tr><td>3. 燃烧和火灾</td><td>火灾征兆、烟气危害、灭火介质作用边界</td><td>初起处置与灭火设施选择</td><td>灭火器、探测环境和通道检查</td><td>复燃、误报和环境因素排查</td><td>触发方式与现场安全条件</td><td>T03-T04、T30、T34；S06、S25、S43</td><td>能把燃烧原理连到处置边界</td></tr><tr><td>4. 建筑防火</td><td>防火分区、防烟分区、防火间距、耐火极限、耐火等级、疏散与防火分隔</td><td>卷帘、风阀、门等动作确认</td><td>分隔设施状态和通道检查</td><td>障碍、限位、反馈故障排查</td><td>动作区域、反馈和恢复核对</td><td>T20-T21、T31、T38-T39；S21、S38-S39、S46</td><td>能区分火势边界、烟气边界、建筑间距、构件性能时间和建筑整体等级</td></tr><tr><td>5. 电气消防</td><td>主备电、线路、接地、控制回路与反馈</td><td>控制柜、主备电和设备控制方式</td><td>接线、端子、供电状态检查</td><td>供电、回路、通信分层诊断</td><td>电气测量工具与安全隔离</td><td>T06、T22、T32；S08、S26、S30、S47</td><td>能区分供电、线路和本体问题</td></tr><tr><td>6. 消防设施</td><td>探测—报警—控制—动作—反馈—恢复</td><td>泵组、风机、联动和报警设备操作</td><td>各系统组成、状态和功能检查</td><td>模块、泵组、阀组、风阀故障处理</td><td>输入、显示、动作、反馈、恢复取证</td><td>T08-T10、T23-T24、T33；S02、S19-S22、S26-S49</td><td>能沿信号链解释完整系统行为</td></tr><tr><td>7. 初起火灾处置</td><td>设施动作服务于报警、疏散和灭火安全</td><td>报警、疏散、现场保护</td><td>器材可用性和通道状态</td><td>复燃风险、停用和临时防护</td><td>测试前通知、清场和恢复</td><td>T07、T11、T17、T34；S01、S21、S25</td><td>能先保人身安全再处理设备</td></tr><tr><td>8. 计算机基础</td><td>控制器、图形显示、日志和通信链路</td><td>查询、消音、复位和记录</td><td>打印、日志、显示状态检查</td><td>信息、权限、通信故障排查</td><td>时间、地址、原始记录和追溯</td><td>T13、T18、T25、T35；S01、S07、S09、S31</td><td>能从界面证据追到现场状态</td></tr><tr><td>9. 法律法规与技术标准</td><td>依据决定方法、权限和判定边界</td><td>按说明书、规程和评分表操作</td><td>按适用周期/项目核对</td><td>授权、停用、维修和复测边界</td><td>选依据、仪器、方法并写明版本</td><td>T05、T12、T26、T36；S04、S05、S11-S14</td><td>能先找适用依据再下结论</td></tr><tr><td>10. 安全生产与职业健康</td><td>供电、压力、机械运动、烟气等风险控制</td><td>授权、监护、清场、恢复</td><td>PPE、现场条件和隔离状态</td><td>断电验电、隔离、升级处理</td><td>仪器安全、测试后放电和现场复原</td><td>T14、T19、T27、T37；S04、S07-S10、S12、S21</td><td>能说出停止条件和安全红线</td></tr></tbody></table><h3 id="表格的逐项使用法" tabindex="-1">表格的逐项使用法 <a class="header-anchor" href="#表格的逐项使用法" aria-label="Permalink to &quot;表格的逐项使用法&quot;">​</a></h3><ol><li><strong>理论回链</strong>：先读本章知识页，写出至少一个“原理→设备行为”的因果句；</li><li><strong>项目回链</strong>：在对应操作、保养、维修、检测页各找一个步骤，标出对象、预期结果和恢复状态；</li><li><strong>题卡验证</strong>：先看 L1/L2，再看 L3 或综合场景；无法解释错误选项时回看理论，不只背答案；</li><li><strong>闭环复述</strong>：随机选一项设备，用“前置安全—输入/操作—显示—现场动作—反馈—恢复—记录”复述；</li><li><strong>留痕</strong>：记录不会的章节、项目和题号，下一轮只回看这些位置。</li></ol><h2 id="九、综合复习路径" tabindex="-1">九、综合复习路径 <a class="header-anchor" href="#九、综合复习路径" aria-label="Permalink to &quot;九、综合复习路径&quot;">​</a></h2><ul><li><strong>第一轮：十章理论串联</strong>：按 1→10 章完成每章的原理因果句和对应 T 题，重点补齐消防设施、电气、安全、法规四个连接点；</li><li><strong>第二轮：按设备横向复习</strong>：分别走报警系统、水系统、其他消防设施三条线，每条线都完成“组成—正常—动作—反馈—故障—恢复”；</li><li><strong>第三轮：按职业功能纵向复习</strong>：依次做操作、保养、维修、检测，使用同一设备比较四种工作的目的、证据和记录；</li><li><strong>第四轮：综合场景复盘</strong>：从 S23-S25 及相关 S26-S49 场景中挑选问题，先写影响范围和安全边界，再写处理与复测，不先猜结论；</li><li><strong>第五轮：依据与边界复核</strong>：对涉及数值、动作时间、允许误差、授权和地方考核的内容，回查现行标准、方案、说明书和当批次评分表。</li></ul><h2 id="十、学习完成自查" tabindex="-1">十、学习完成自查 <a class="header-anchor" href="#十、学习完成自查" aria-label="Permalink to &quot;十、学习完成自查&quot;">​</a></h2><p>读完本页和对应项目卡后，应能不看答案说出：</p><ol><li>报警系统、水系统和其他消防设施分别解决什么问题；</li><li>每类设备的主要组成、输入、控制、输出和反馈；</li><li>操作、保养、维修、检测四项工作的区别；</li><li>至少五类检测工具的用途和使用前检查；</li><li>检测前、中、后的规范步骤；</li><li>单点故障与成片故障的排查思路差异；</li><li>“动作但无反馈”“有水但无报警”“灯亮但系统故障”等现象不能直接判合格的原因；</li><li>哪些数值和操作必须回查标准、方案、说明书或地方评分表；</li><li>维修和检测结束时必须确认哪些恢复状态；</li><li>理论知识如何解释一个具体技能场景。</li></ol><blockquote><p>如果以上问题不能回答，不要急着刷题，回到相应理论章节、设备项目卡和 <code>skill/04-repair.md</code>、<code>skill/05-detection.md</code> 重新学习。</p></blockquote>`,113)])])}const u=d(n,[["render",r]]);export{b as __pageData,u as default};
